<?php require_once __DIR__.'/includes/api.php';if(current_user())go('dashboard.php');$error='';$ref=trim($_GET['ref']??'');if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$r=api_call('auth/register','POST',['name'=>trim($_POST['name']??''),'username'=>trim($_POST['username']??''),'contact'=>trim($_POST['contact']??''),'password'=>(string)($_POST['password']??''),'referral_code'=>trim($_POST['referral_code']??'')]);if(!empty($r['ok'])){flash('success','Account created. Please sign in.');go('login.php');}$error=$r['error']??'Could not register.';}$title='Create account';?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?></title><link rel="stylesheet" href="assets/css/style.css"></head><body><div class="auth"><section class="auth-card"><div class="auth-brand"><span class="brand-mark">GM</span>ERAN+</div><h1>Create test account</h1><p>Use placeholder details. Your account is stored by the separate Admin API.</p><?php if($error):?><div class="flash error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><div class="field"><label>FULL NAME</label><input class="input" name="name" required></div><div class="field"><label>USERNAME</label><input class="input" name="username" required></div><div class="field"><label>EMAIL OR PHONE</label><input class="input" name="contact" required></div><div class="field"><label>PASSWORD (8+ CHARACTERS)</label><input class="input" type="password" name="password" minlength="8" required></div><div class="field"><label>REFERRAL CODE</label><input class="input" name="referral_code" value="<?=e($ref)?>"></div><button class="button button-primary" type="submit">CREATE ACCOUNT</button></form><p style="text-align:center;margin-top:18px">Already registered? <a href="login.php" style="color:#bf97ff">Sign in</a></p></section></div></body></html>
